public final class FlowNetwork {
    private final int[][] capacities;
    private final Vertex[] vertices;

    public FlowNetwork(int[][] capacities) {
        validate(capacities);
        this.capacities = IntMatrix.copyOf(capacities);
        this.vertices = createVertices(capacities.length);
    }

    public int size() {
        return capacities.length;
    }

    public boolean contains(Vertex vertex) {
        return vertex != null && vertex.index() < capacities.length;
    }

    public Vertex vertexAt(int index) {
        if (index < 0 || index >= vertices.length) {
            throw new IllegalArgumentException("Vertex index must belong to the network.");
        }
        return vertices[index];
    }

    public Vertex[] vertices() {
        return vertices.clone();
    }

    public int capacity(Vertex from, Vertex to) {
        validateVertex(from);
        validateVertex(to);
        return capacities[from.index()][to.index()];
    }

    public int[][] copyCapacities() {
        return IntMatrix.copyOf(capacities);
    }

    private void validateVertex(Vertex vertex) {
        if (!contains(vertex)) {
            throw new IllegalArgumentException("Vertex must belong to the network.");
        }
    }

    private static void validate(int[][] capacities) {
        if (capacities == null || capacities.length == 0) {
            throw new IllegalArgumentException("Graph must not be empty.");
        }

        int size = capacities.length;
        for (int row = 0; row < size; row++) {
            if (capacities[row] == null || capacities[row].length != size) {
                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
            }
            for (int column = 0; column < size; column++) {
                if (capacities[row][column] < 0) {
                    throw new IllegalArgumentException("Capacities must be non-negative.");
                }
            }
        }
    }

    private static Vertex[] createVertices(int size) {
        Vertex[] vertices = new Vertex[size];
        for (int index = 0; index < size; index++) {
            vertices[index] = new Vertex(index);
        }
        return vertices;
    }
}

public final class FordFulkersonSolver implements MaxFlowAlgorithm {
    private final AugmentingPathFinder pathFinder;

    public FordFulkersonSolver() {
        this(new BreadthFirstAugmentingPathFinder());
    }

    public FordFulkersonSolver(AugmentingPathFinder pathFinder) {
        if (pathFinder == null) {
            throw new IllegalArgumentException("Path finder must not be null.");
        }
        this.pathFinder = pathFinder;
    }

    @Override
    public MaxFlowResult solve(FlowProblem problem) {
        ResidualNetwork residualNetwork = new ResidualNetwork(problem.network());
        int maxFlow = 0;

        while (true) {
            java.util.Optional<AugmentingPath> path = pathFinder.find(residualNetwork, problem);
            if (path.isEmpty()) {
                return new MaxFlowResult(problem, maxFlow, residualNetwork.asFlowNetwork());
            }

            residualNetwork.augment(path.get());
            maxFlow += path.get().bottleneck();
        }
    }
}

public final class MaxFlowResult {
    private final FlowProblem problem;
    private final int maxFlow;
    private final FlowNetwork residualNetwork;

    public MaxFlowResult(FlowProblem problem, int maxFlow, FlowNetwork residualNetwork) {
