            throw new IllegalArgumentException("Problem must not be null.");
        }
        if (residualNetwork == null) {
            throw new IllegalArgumentException("Residual network must not be null.");
        }

        this.problem = problem;
        this.maxFlow = maxFlow;
        this.residualNetwork = residualNetwork;
    }

    public FlowProblem problem() {
        return problem;
    }

    public int maxFlow() {
        return maxFlow;
    }

    public FlowNetwork residualNetwork() {
        return residualNetwork;
    }

    public int getMaxFlow() {
        return maxFlow;
    }

    public int[][] copyResidualGraph() {
        return residualNetwork.copyCapacities();
    }
}

public final class FordFulkersonMaxFlow {
    private FordFulkersonMaxFlow() {
    }

    public static void main(String[] args) {
        FlowProblem problem = FlowProblem.fromCapacities(new int[][] {
            {0, 16, 13, 0, 0, 0},
            {0, 0, 10, 12, 0, 0},
            {0, 4, 0, 0, 14, 0},
            {0, 0, 9, 0, 0, 20},
            {0, 0, 0, 7, 0, 4},
            {0, 0, 0, 0, 0, 0}
        }, 0, 5);

        MaxFlowAlgorithm algorithm = new FordFulkersonSolver();
        MaxFlowResult result = algorithm.solve(problem);

        System.out.println("The maximum possible flow is " + result.maxFlow());
    }
}

public final class FlowProblem {
    private final FlowNetwork network;
    private final Vertex source;
    private final Vertex sink;

    public FlowProblem(FlowNetwork network, Vertex source, Vertex sink) {
        if (network == null) {
            throw new IllegalArgumentException("Network must not be null.");
        }
        if (!network.contains(source) || !network.contains(sink)) {
            throw new IllegalArgumentException("Source and sink must be valid vertices in the network.");
        }

        this.network = network;
        this.source = source;
        this.sink = sink;
    }

    public static FlowProblem fromCapacities(int[][] capacities, int source, int sink) {
        FlowNetwork network = new FlowNetwork(capacities);
        return new FlowProblem(network, network.vertexAt(source), network.vertexAt(sink));
    }

    public FlowNetwork network() {
        return network;
    }

    public Vertex source() {
        return source;
    }

    public Vertex sink() {
        return sink;
    }
}

public final class Vertex {
    private final int index;

    public Vertex(int index) {
        if (index < 0) {
            throw new IllegalArgumentException("Vertex index must be non-negative.");
        }
        this.index = index;
    }

    public int index() {
        return index;
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof Vertex)) {
            return false;
        }

        Vertex vertex = (Vertex) other;
        return index == vertex.index;
    }

    @Override
    public int hashCode() {
        return Integer.hashCode(index);
    }

    @Override
    public String toString() {
        return "Vertex[" + index + "]";
    }
}

public final class ResidualNetwork {
    private final int[][] capacities;
    private final Vertex[] vertices;

    public ResidualNetwork(FlowNetwork network) {
        capacities = network.copyCapacities();
        vertices = network.vertices();
    }

    public int size() {
        return capacities.length;
    }

    public boolean hasCapacity(Vertex from, Vertex to) {
        return capacity(from, to) > 0;
    }

    public Vertex vertexAt(int index) {
        return vertices[index];
    }

    public Vertex[] vertices() {
        return vertices.clone();
    }

    public int capacity(Vertex from, Vertex to) {
        return capacities[from.index()][to.index()];
    }

    public void augment(AugmentingPath path) {
        for (Vertex vertex = path.sink(); !vertex.equals(path.source()); vertex = path.parentOf(vertex)) {
            Vertex previous = path.parentOf(vertex);
            capacities[previous.index()][vertex.index()] -= path.bottleneck();
            capacities[vertex.index()][previous.index()] += path.bottleneck();
        }
    }

    public FlowNetwork asFlowNetwork() {
        return new FlowNetwork(capacities);
    }
}

